select clock_timestamp() as observed_at,current_user as executor,to_regclass('notification_delivery.event_settings') is not null as event_settings_present,to_regclass('notification_delivery.event_jobs') is not null as event_jobs_present,(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'bodyMd5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='notification_delivery' and p.proname in('event_mode_allowed','enqueue_event','queue_notification_event','queue_call_event','cleanup_event_jobs')) or(n.nspname='public' and p.proname in('claim_notification_event_dispatch','notification_event_dispatch_allowed','finish_notification_event_dispatch'))) as candidate_functions,(select coalesce(jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid)) order by tgname),'[]'::jsonb) from pg_trigger where tgname in('notification_event_dispatch_queue','notification_call_event_dispatch_queue')) as candidate_triggers,(select coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) order by version),'[]'::jsonb) from supabase_migrations.schema_migrations where name ilike '%notification_event_dispatch%') as candidate_migrations,(select count(*) from pg_stat_activity where pid<>pg_backend_pid() and state='active' and (query ilike '%notification_delivery.event_%' or query ilike '%notification_event_dispatch%')) as candidate_active_statements,(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='net' and c.relname in('http_request_queue','_http_response')) as pg_net_tables,obj_description(to_regnamespace('business_auth'),'pg_namespace') as business_schema_marker,(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='send_member_support_reply') as support_reply_functions,to_regnamespace('music_library') is not null as music_schema_present,(select coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name)),'[]'::jsonb) from supabase_migrations.schema_migrations where name='private_media_readiness_storage_references') as readiness_migration;
